C = []
def cl(feature, claim, key, quote="", page=""):
    s = S[key]
    if quote:
        assert len(quote.split()) < 12, (quote, len(quote.split()))
    C.append(dict(feature=feature, claim=claim, source=s["title"], url=s["url"], quote=quote, page=page or s["title"]))

# ---- premise: style guide existence, scope, availability
cl("house style guide (existence and scope)","A written WotC house style guide exists — 'D&D Style Guide: Writing and Editing' v1.04a (©2013), built on Chicago 16 and Merriam-Webster 11 — and it governs typography, numerals, verb collocations, capitalization and tone, with no rule at all on boxed/read-aloud text.","sg104","D&D Style Guide: Writing and Editing")
cl("house style guide (revision v1.08a)","A later revision, v1.08a (©2018, circulated as 'updated January 2019'), keeps the same structure (Chicago 17 now) and adds headings hierarchy, sidebar, gender-suffix, 'fellowship vs party' and edition-naming rules; it still contains nothing on boxed text or read-aloud prose.","sg108","Avoid overusing sidebars.")
cl("house style guide (public release window)","The style guide was released publicly on DMs Guild around October 2018 as one of four free PDFs (IP guide, adventure guide, style guide, Forgotten Realms guide) that had previously gone only to official-play writers.","ensg","")
cl("house style guide (public release window)","On 2019-02-22 the DMs Guild account announced an updated House Style Guide listing for creators, noting it adds tips on gender-neutral language.","sa3","An updated #DnD House Style Guide is now on #DMsGuild")
cl("house style guide (availability lapsed)","The Kind GM's post on the creator resource carries a May 2020 commenter report that the material was no longer available, which the author acknowledged — so the public window was roughly 2018–2020.","kindgm","")
cl("house style guide (community says none published)","Community writers on either side of that window report no official guide: Half-Cover (2017) says WotC 'has not yet published the official style guide', Old Dungeon Master (2015) compiled one from 3.5/4e guides ('Perhaps they have one and I just couldn't find it'), and Blog of Holding (2025) says of the 2024 rules 'it annoys me not to have an official style guide'.","halfcover","has not yet published the official style guide")
cl("house style guide (community says none published, 2024 rules)","Paul Hughes built an unofficial 2024 style guide because no official one for the 2024 rules is available to the public.","boh","it annoys me not to have an official style guide")
cl("house style guide (freelancer distribution)","Work-for-hire WotC freelancers receive the D&D House Style Guide, the 5e Word template, pitch examples and lore documents at contract start, and drafts are formatted with them.","poc","")
cl("house style guide (organized-play distribution)","The official Adventurers League Dungeoncraft guide tells authors they must use the provided template and 'formatting standards as presented in the template' and be familiar with the D&D Style Guide, which it says is also provided.","dcraft","You should be familiar with the D&D Style Guide")
cl("house style guide (organized-play distribution)","The 2023 Dungeoncraft Design Guide (effective 2023-11-09) again requires a specific template and familiarity with the D&D Style Guide; a poster frames this as organized play needing 'more guiderails than your usual table does'.","endc","more guiderails than your usual table does")
cl("house style guide (third-party use)","Kobold Press ran a 'Designing with Style' series that explicitly 'breaks down the official 5th-edition style guide', quoting its Common Pitfalls section verbatim — evidence the guide was public and treated as canonical by third-party 5e designers.","kobstyle","breaks down the official 5th-edition style guide")

# ---- house style: concrete rules from the guide
cl("second person in rules text","The guide's stated reason for second person in rules text is gender neutrality: 'In rules text, we often achieve gender neutrality by writing in the second person.'","sg104","writing in the second person")
cl("singular they (2013 vs 2018 policy)","v1.04a forbids 'they'/'their' as singular pronouns except in dialogue; v1.08a reverses this 'in a departure from our past usage' but tells writers to rely on it only when no pleasing alternative exists.","sg108","but don't abuse this liberty")
cl("verb–object collocations","The guide fixes the game's verb idiom in a list: you cast a spell, deal damage, make a saving throw that succeeds or fails, make an attack that hits or misses, take damage, regain hit points, score a critical hit, use a feature.","sg104","You make a saving throw, and it succeeds or fails")
cl("'must succeed on' vs 'must make'","Common Pitfalls: never write 'must make a DC 15 Strength check' unless success and failure are described next; the canonical form is 'must succeed on'.","sg104","You must succeed on a DC 15 Strength check")
cl("Ability (Skill) check pattern","Third-party style guidance derived from the WotC guide: skill checks are always written as '[Ability Score] ([Skill])', outcomes are stated for success and failure, and multi-skill checks name at most two skills for brevity.","kobstyle","always written as [Ability Score] ([Skill])")
cl("numerals in rules vs words in narrative","Rules text uses numerals for any game quantity ('regains 3 hit points', 'lasts for 1 round', 'The room is 20 feet square') while narrative time and distance are spelled out ('slept for six hours', 'fifty miles apart').","sg104","the characters slept for six hours")
cl("abandoned 4e terms ('save', 'result')","The guide explicitly retires 4e usages: 'save' as 'successful saving throw' and 'result' as 'the number rolled on a die' — 'We have abandoned that practice.'","sg104","We have abandoned that practice")
cl("'points of damage' banned","Write 'deals 10 fire damage', not '10 points of fire damage'; write 'hit point maximum', not 'maximum hit points'; 'magic item' is never 'magical item'.","sg104","Avoid referring to points of damage")
cl("capitalize / italicize term classes","Capitalize ability scores, Armor Class, class features, Difficulty Class, feats, languages, planes, skills, racial/monster traits; italicize spell and magic-item names as titles (the spell wall of fire produces a wall of fire).","sg104","")
cl("inline subhead punctuation","Inline subheads (heading 4) end with terminal punctuation, not a colon — 'Keen Senses. You have proficiency…' — and are set in bold italics; bolded stat-block fields are a different thing.","sg104","followed by terminal punctuation, not a colon")
cl("no weeks or months in rules","Because a Realms week is a tenday, rules durations are given in days, never weeks or months (years are allowed).","sg104","say a game effect lasts for 7 days")
cl("'not' contractions encouraged","The guide encourages contractions formed with 'not' (don't, can't, wasn't) and warns against ambiguous ones like 'who's' — a deliberately conversational register for rules.","sg104","")
cl("High Fantasy tone rule","The only tone guidance in the guide: D&D is high fantasy about small teams; humor or tragedy is fine if it doesn't overtake the tone, tested against Lord of the Rings / Game of Thrones — 'ring wraiths aren't used for gags'.","sg104","ring wraiths aren't used for gags")
cl("'party' not 'fellowship' (v1.08a)","v1.08a adds a diction rule: avoid 'fellowship' for adventuring groups because D&D companies are 'often fractious or more mercenary'; use group, band, company or especially 'party'.","sg108","often fractious or more mercenary")
cl("edition naming (v1.08a)","v1.08a switches from '5th Edition' to lowercase 'fifth edition', preferably as a modifier ('the fifth edition Dungeon Master's Guide').","sg108","")
cl("gender-specific suffixes (v1.08a)","v1.08a: write 'priest', 'actor', 'god' regardless of gender; '-ess' forms only in in-world titles.","sg108","Avoid gender-specific suffixes whenever possible")
cl("headings and sidebars (v1.08a)","v1.08a requires descending the heading hierarchy without skipping levels, forbids inline subheads used merely for emphasis, and says the best sidebars 'can appear anywhere on a page and still make sense'.","sg108","")
cl("in-world tenday rule vs WotC practice","A poster notes the style guide bans 'week' in favor of 'tenday' while WotC's own hardcovers violate the rule — house style is aspirational, not uniformly applied.","ensg","")

# ---- inferred/community house-style observations
cl("formulaic feature wording","Half-Cover infers from the books that spells and saving throws use 'very specific wording' and that features always spell out interactions (e.g., already having a cantrip), with fixed section order (starting equipment before class features).","halfcover","a strict style guide that all D&D sections adhere to")
cl("present tense, not future 'will'","A community-compiled 5e writer's guide: 'Write in the present tense', avoiding 'will' for NPC/monster actions ('the golem attacks').","odm2015","Wherever possible, avoid using the future tense")
cl("2024 capitalization map","In 2024 text, Bonus Action, Advantage/Disadvantage, Hit Points, Armor Class, Death Saving Throw, Proficiency Bonus, Challenge Rating and D20 Test are capitalized while ability, action, saving throw, skill, spell and feat stay lowercase; monster-name capitalization is inconsistent.","boh","")
cl("2024 capitalization signals glossary","Justin Alexander: 2024 capitalizes defined terms (Cone, Target) to flag Rules Glossary entries, but definitions then live only in the glossary, scattering the targeting rules across pp. 236–238, 361, 364 and 376.","alexgloss","")
cl("standardized condition phrasing (2024)","2024 condition text is standardized to mechanical statements — 'Your Speed is 0 and can't increase' replaces 2014's 'can't move' — and 'Utilize', 'Study', 'Influence' and 'D20 Test' become defined capitalized terms.","odm2024","Your Speed is 0 and can't increase")
cl("teach-first structure and annotated play example (2024)","The 2024 PHB opens with a How to Play chapter and a two-column example of play annotated with the applicable rules; Crawford frames the rewrite as 'teaching you how to play', contrasting 2014 which 'jumps right into character creation'.","wgphb","teaching you how to play")
cl("glossary as information design (2024)","Idle Cartulary judges the 48-page rules section plus 18-page glossary 'absolutely stellar information design' and 'an incredibly confident book', though terms like Influence action lack definition where used.","idle","absolutely stellar information design")
cl("5e natural-language intent (designer)","Mearls' 2013 Legends & Lore argument, as quoted: feat names like 'Rapid Shot and Precise Shot are abstract things that aren't really clear', whereas describing a fighter as an archer 'makes sense to anyone'; rules are 'a shared language'.","tenkar","a shared language")
cl("5e natural-language intent (community inference)","A 2014 EN World thread infers that 5e designers chose rulings over exact language, which lets them 'use more natural language' — community inference from Mearls' videos, not a designer statement about prose.","enphil","use more natural language")
cl("editing layers: precision vs emotion","5e core-book editor Scott Fitzgerald Gray: mechanics editing needs precision in how a book 'fits in with the game as a whole', narrative editing needs flow and pacing, and prose editing serves 'the emotional language of the game' so readers feel like a character in the world.","gray","the emotional language of the game")

# ---- 2024 DMG / adventure-format shifts
cl("adventure boilerplate removed (doors, boxed text)","Perkins says every adventure for a decade had to re-explain doors, so the 2024 DMG codifies them; Wyatt calls re-explaining boxed text in every adventure a 'stupid little thing' the DMG (p. 9) now covers, pending the editing team.","sr2","stupid little thing")
cl("brevity as DMG editorial rule","Perkins on the 2024 DMG: 'everything in there better be cracking on topic'; the sample adventures use 'tight and short' read-aloud scripts to jog the DM's memory, avoiding his earlier 32-page adventures.","sr1","tight and short")
cl("Curse of Strahd vs Storm King's Thunder boxed text","DMDavid observes Perkins boxed every location in Curse of Strahd, even empty rooms, and that his next adventure, Storm King's Thunder, 'omits almost all read-aloud text' — the two extremes of WotC 5e practice.","dmdkey","omits almost all read-aloud text")
cl("2025 Monster Manual one-phrase characterization","Every 2025 MM entry opens with a single characterizing phrase ('tentacled subterranean trapper', 'guardian manifestation of the divine'); lore is 'compact but effective' though 'a little too compact for my taste'; quote boxes appear on some entries.","enmm","tentacled subterranean trapper")
cl("2025 Monster Manual flavor-mechanics alignment","TheGamer: 'The flavor has amped up narratively, and the mechanics have followed' (angels wield light, kenku use shadow-magic daggers); there is no lore glossary.","tgmm","")
cl("sourcebook narrator marginalia","Xanathar's Guide carries 'little notes that run as commentary throughout the book, usually a sort of joke or snipe about the subject matter', continuing the Volo's device but less relevant on a mechanics-heavy book.","skyland","a sort of joke or snipe about the subject matter")

# ---- boxed text: length
cl("boxed-text length (two-sentence rule)","Dyson Logos, citing Decker and Noonan's 2005 GenCon table observations, holds that a DM gets two sentences before players stack dice; players missed dimensions, exits and monster counts in longer boxed text.","dyson","you get two sentences. Period.")
cl("boxed-text length (Noonan/Decker via forum)","A 2025 EN World poster re-cites the 2005 Noonan/Decker WotC article: two sentences, 'DMs who didn't used boxed text had more engagement', cold reading is worse than personal phrasing, 'Ditch the boxed text and use your own words' — upstream article not fetched, single-lineage claim.","enwra","Ditch the boxed text and use your own words")
cl("boxed-text length (community ceiling)","Thread posters set ceilings of 'no more than two sentences' (GM Lent) or '3 to 5 sentences at most' with listed details for closer investigation (el-remmen).","enwra","3 to 5 sentences at most")
cl("boxed-text length (four sentences, under 100 words)","Shawn Merwin's D&D Beyond craft column: an opening should be 'Four sentences, and less than 100 words'; avoid 'paragraph after paragraph of boxed text'.","ddbmerwin","Four sentences, and less than 100 words")
cl("boxed-text length (three lines, never five)","A 5e designer describes evolving from verbose 5e style to bullets to boxed text that is 'typically three lines, and never longer than five' because it sped play and set a base tone per room.","reviv","typically three lines, and never longer than five")
cl("boxed-text length (under 250 words, cut 25%)","Sly Flourish: a read-aloud is a tiny story told in 'less than 250 words'; if editing didn't remove 25% you didn't try; 'Keep it short and keep it powerful.'","slyra","less than 250 words to tell it")
cl("boxed-text length (paragraph break = too long)","Outside introductions, a boxed text with a paragraph break 'isn't already too long by half' is rare; villain dialogue should be broken into ~six-second (one-round) statements.","dmsw","isn't already too long by half")
cl("boxed-text length (attention after three sentences)","Justin Alexander: 'boxed text is often too long'; break 'freeze-frame' text into actionable chunks and stop at the reaction point so players respond before the world moves on.","alex13","boxed text is often too long")
cl("key length (five sentences)","Gus L.: a basic room key is five sentences maximum; longer only for puzzles and NPCs — 'no one wants to read a three page key'.","adg","no one wants to read a three page key")
cl("read-aloud length at the table (critic)","Bryce Lynch: long read-aloud at each location means 'the players are almost certainly going to be playing with their phones', even when, rarely, the prose is good.","tfpdeath","")

# ---- boxed text: person, tense, control
cl("third person over second person in boxed text","Merwin's core fix: 'Move from the second-person point of view to the third person' — 'The bloated corpse of a headless dragon dominates the center of this small clearing' instead of 'As you enter the clearing, you notice…' — so text cannot dictate PC actions or feelings.","chmerwin","Move from the second-person point of view to the third person")
cl("no dictated PC actions or emotions","Merwin's D&D Beyond rules: never 'as you approach' or 'you enter'; never 'stunned', 'terrified', 'heart pounds'; no game-mechanics terms used non-mechanically in boxed text.","ddbmerwin","")
cl("remote-control text","Alexander names the pitfall 'remote-control text': 'You step forward', 'You smile', or declaring 'the thoughts or feelings' of PCs; show the scene, 'don't tell them how they're reacting to it'.","alex13","the thoughts or feelings")
cl("no predicting party movement","Dyson: bad boxed text 'predicts the future for the party (upon approaching…)' or commands behavior ('you stand in shock'); cure is one or two simple sentences or a point-form list.","dyson","predicts the future for the party")
cl("second-person subjective as engagement (dissent)","DM's Workshop argues the opposite of Merwin: shift from third-person objective ('A 200-foot waterfall cascades') to second-person subjective ('You see a majestic waterfall') so the DM addresses the players rather than 'the empty air'.","dmsw","the empty air")
cl("perspective-neutral, compass directions","Key-writing rule: 'Write without assumption of perspective' about entry point; use compass directions ('east wall'), never relative ones ('far side').","baatag","Write without assumption of perspective")
cl("no emotional direction, cardinal directions","Designing Dungeons: keep descriptions 'short and punchy', don't tell players what to feel, use east/west not left/right, and let the map carry redundant door descriptions.","dd10","short and punchy")
cl("no 'if/then' or direct address (critic)","Readers summarizing Lynch's standards: don't provide conclusions, avoid 'if/then' constructs as padding, and don't address the party directly in read-aloud.","intodark","")
cl("present tense in conditionals (drop 'will')","Robin D. Laws: in hypothetical RPG text drop 'will' — 'If the agents reach the safe house, Keletny burns the car'; also avoid passive voice and 'to be' + verb pairs.","laws","Keletny burns the car")
cl("present vs future tense (editor)","Ray Vallese's editor's guide devotes a section to 'using present tense instead of future tense' and to 'avoiding rampant capitalization' — two habits of RPG manuscripts an editor corrects.","vallese","using present tense instead of future tense")

# ---- boxed text: content and diction
cl("describe what can be sensed, not what can't","Merwin's epistemic rule: 'Describe everything the characters can sense, but not what they cannot' — no crate contents, but never omit the 50-foot chasm.","chmerwin","Describe everything the characters can sense, but not what they cannot")
cl("'seems/appears' hedges banned","Words like 'seems' and 'appears' telegraph tricks: 'If something \"appears to be\" to the characters, it \"is\"' — let Perception checks, not hedges, create the distinction.","chmerwin","If something 'appears to be' to the characters, it 'is'")
cl("Chekhov relevance filter","Include only environmental details PCs will interact with; the smell of flowers can go 'unless you happen to be DMing for a party comprised solely of elves or florists'.","chmerwin","a party comprised solely of elves or florists")
cl("no novelistic urge / monologues","'Avoid the novelist/dramatist urge': no evil soliloquies, no coronation cutscenes; keep passages short and let PCs act.","chmerwin","Avoid the novelist/dramatist urge")
cl("read aloud to test","'Read your boxed text aloud to check readability' — tongue-twisters, unintended alliteration and odd phrasing are invisible on the page.","ddbmerwin","Read your boxed text aloud to check readability")
cl("evocative not conclusory","Lynch's most-cited rule as summarized: replace the abstract judgment ('a cruel bully') with the concrete action ('Manfred takes a leak on Tobias's bedroll'); aim for 'the telltale sensory detail, rather than the generic abstract trait'; specificity, not mere detail.","intodark","the telltale sensory detail, rather than the generic abstract trait")
cl("terse-and-evocative register (critic's scale)","tenfootpole grades language on a four-point scale topped by 'Succinct and evocative', lists 'Terse writing style' and 'Evocative atmosphere' as requirements, and states 'Boxed text is usually not a good thing'.","tfpstd","Succinct and evocative")
cl("overwritten fantasy register","Lynch praises one 5e read-aloud for avoiding 'the overwritten fantasy drivil that is present in most read aloud' and for capturing a social scene in progress.","tfpdeath","the overwritten fantasy drivil that is present in most read aloud")
cl("filler-adjective purge","Skerples: use find-and-replace to hunt filler words ('little, big, grand, tall, dark') and swap in evocative choices; 'Every sentence needs to fight for its life in a dungeon key.'","skerp","Every sentence needs to fight for its life")
cl("concrete over generic descriptors","Gus L.: not 'evil idol' but 'toothy glare' or 'sharp edged obsidian'; include non-visual senses but never room history, future or emotions.","adg","sharp edged obsidian")
cl("one sensory hook","Celeste Conowitch: 'keep it simple with a few powerful details' — the facts plus one detail ('reeks of garlic') that gives the room a story; never name the monster in narration.","kobpaint","keep it simple with a few powerful details")
cl("three-of-five senses formula","Alexander's room formula: list notable things with positions, tag them with three of the five senses ('Try to include three of them'), then add a verb; NPCs get an action, clothing and one trait — 'you're not describing their headshot'.","alexdesc","Try to include three of them")
cl("five-senses show-don't-tell","Anne K. Brown's essay (as reported): use all five senses and show rather than tell ('you detect orcs' is the failure), but don't over-invest in sensory prose players can't use.","gball","")
cl("newspaper-lead ordering","Chris Doyle's essay (as reported): write read-aloud like a newspaper lead — immediate threat first ('GIANT SLAVERING OGRE'), secondary details after, lower-level details left for searching.","gball","GIANT SLAVERING OGRE")
cl("fantastical vs instruction-manual register","Sly Flourish: use fantastical language — 'quit writing read-aloud text that sounds like it came from Ikea instructions' — and make sure 'every word has a place in it'.","slyra","sounds like it came from Ikea instructions")
cl("punchy, emotionally slanted commercial boxed text","A review of dScryb's commercial boxed text finds it 'very punchy and to the point', carrying 'emotional information, motivations, or default assumptions' and sometimes 'selling' the creature or place.","gsdscryb","very punchy and to the point")
cl("active voice and expletive cuts (editor via critic)","Vallese's book, per Lynch: cut 'there is/are' openings ('An old wise man watches over the children'), prefer active constructions, and reorder stacked modifiers ('Its wormlike body is thin and scaly').","tfpvallese","Its wormlike body is thin and scaly")
cl("rules are for breaking (editor)","Vallese: 'Do you have to follow all of these tips all the time? Nope… Just be sure you understand the rules before you break them' — vary to keep flavor and voice.","gsval","Just be sure you understand the rules before you break them")
cl("plural constructions for neutrality","Laws' fifth key: use plurals to dodge gendered pronouns — 'Characters can leave their pistols at the door.'","laws","Characters can leave their pistols at the door")
cl("'to be' replacement / show through play","BAATAG rule 7: replace 'to be' verbs with active ones and show rather than tell — describe details that reveal information through play.","baatag","")
cl("boxed text as prompts ('narrative text')","Merwin prefers the term 'narrative text': 'a series of prompts that can help your game flow more smoothly'; 'Excellent boxed text does a lot of heavy lifting' for atmosphere.","sa2","Excellent boxed text does a lot of heavy lifting")
cl("market demand for boxed text","Merwin (2019): 'A majority of DMs out there WANT boxed text (well-written hopefully)' — omitting it is 'a risk', even though streamers rarely read it.","sa1","A majority of DMs out there WANT boxed text")

# ---- DM text / key structure
cl("sequencing over format","Alexander rejects 3e's Traps/Creatures/Tactics/Development/Treasure key format because writers 'fill the format' and information lands out of play sequence: the ogre in the middle comes first, the goblin behind the tapestry does not.","alexkey","fill the format")
cl("essential key components","The essential key: room title, boxed text ('seen in a glance'), reactive checks front-loaded, bold-titled significant elements, developing details from general to specific, a GM-background tag — and 'Complete sentences are overrated'.","alexkey2","Complete sentences are overrated")
cl("bold interactables, monsters last","Designing Dungeons: first paragraph describes 'everything immediately observable' with interactables in bold; list contents in the order described; monsters go last in the first description but first in later keying.","dd10","Write a paragraph that describes everything immediately observable")
cl("minimal bolding, inhabitants first","Gus L.: '3 or 4 bolded words maximum' per complex room, each keyed to a follow-up paragraph; start with the room's inhabitants, then dangers, valuables, then hidden items tagged '(trap)' or '(hidden)'.","adg","3 or 4 bolded words maximum")
cl("plain paragraphs as reference (anti-bullet)","BAATAG rule 2: no bullets or bolding by default — 'Plain text paragraphs still need to serve as reference documents'; later paragraphs are one topic each, recognizable from the first few words.","baatag","Plain text paragraphs still need to serve as reference documents")
cl("1–2 sentence sensory key then interactables","Cygnus's rewrite format: name, a 1–2 sentence description touching several senses ('what the characters can immediately perceive'), listed interactables, nested details, stat lines last — explicitly to avoid long boxed text.","lat","what the characters can immediately perceive")
cl("Courtney Campbell bold/arrow key economy","Tad Davis describes Campbell's economy method: bold for immediately visible items, arrows to hidden ones, indentation for stacking, omitting non-essential words, with sound/smell/breeze cues.","arsph","")
cl("seven-word density","Designing Dungeons cites Courtney Campbell's target of encoding 'everything you need to run successfully in seven words'.","dd10","")
cl("tables over prose, cut mercilessly","Skerples: 'Cut mercilessly. Turn pages to paragraphs, paragraphs sentences, sentences to tables'; 'Sprawl is the enemy of utility'; begin with what is seen at a glance, then motion, smells, details, hidden information — never 'This room is…'.","skerp","Sprawl is the enemy of utility")
cl("map carries dimensions and exits","Gus L.: 'Maps! Use them.' — never spend key lines on dimensions and exits.","adg","Maps! Use them.")
cl("against boxed text (referee displacement)","Gus L. rejects player-facing boxed text because it discourages referees from reading keys and is 'depreciating one big advantage RPGs have'.","adg","depreciating one big advantage RPGs have")
cl("one-line keys vs the G1 pattern","DMDavid: Gygax 'usually wrote a 1-line note for each room' for Castle Greyhawk, but G1 (1978) gave 'generous descriptions for every location' and 'set the pattern for virtually every adventure to follow'; length should match a location's purpose.","dmdkey","usually wrote a 1-line note for each room")
cl("adventure text is functional","Jobe Bittman (as reported): give 'that which is necessary for the GM to run the scenario and have it make sense, and no more'.","gball","and no more")
cl("subtext in adventure vs rules text","Monte Cook: adventure text states facts plainly and leaves the solution as subtext ('It's better unsaid'); setting text 'Don't be coy about the important stuff'; rules text never uses subtext.","cooksub","It's better unsaid.")
cl("small, excellent, play-tested text","Arnold K.: write snippets, run the dungeon to expose weaknesses, then cut — 'It's better to have a small, excellent dungeon'.","gp","It's better to have a small, excellent dungeon")
cl("scannability as the editor's gap","Lynch faults Vallese's guide for saying nothing about white space, bullets or evocative writing — the DM must 'glance at the page and immediately find' what is needed.","tfpvallese","glance at the page and immediately find")
cl("Perkins: script text jogs memory","Perkins describes the 2024 DMG sample adventures' read-aloud as 'tight and short' scripts whose job is to jog the DM's memory, not to be recited.","sr1","tight and short")

# ---- history and delivery
cl("boxed text origin (1979 tournament)","DMDavid: boxed text entered D&D with Hidden Shrine of Tamoachan, written for the Origins '79 AD&D tournament to give 'a consistent play experience in a competitive environment'.","dmdpic","")
cl("read-aloud cadence problem","'When most speakers read something aloud, their voice takes a different tone and cadence than when they speak extemporaneously', so attention wanders; boxed text also dwells on 'the color of the sunset'.","dmdpic","their voice takes a different tone and cadence")
cl("reading vs paraphrasing (1980s attitude)","Gnome Stew (2008): in the 1980s reading boxed text aloud was 'considered a cardinal sin' among GMs, who were expected to paraphrase; the author later found reading helped immersion; commenters: 'Short box text is fine, long box text is a challenge.'","gsbox","considered a cardinal sin")
cl("rehearsed delivery","DM's Workshop: practice reading text aloud between sessions and match pacing to conversational speech; boxed text is a tool to adapt, not a script to recite.","dmsw","")

out = dict(claims=C, sourcesRead=list(S.values()))
json.dump(out, open("found-dnd-craft.json","w"), indent=1, ensure_ascii=False)

md = []
md.append("# D&D official-content prose — angle: craft essays and writing advice (novelists, editors, designers)\n")
md.append("Sweep date: 2026-09-05. Method: 11 WebSearch rounds (boxed text craft, Lynch/Alexandrian, WotC designers Perkins/Crawford/Mearls/Decker/Noonan/Wyatt, editors Gray/Vallese/Carter/Mohan, AL/DMs Guild guidance, 2014 vs 2024 style, OSR key-writing, sourcebook narrator voice); every cited page fetched and read this session (WebFetch, or curl + local PDF/HTML text extraction where WebFetch was 403'd). Stopping rule: last two rounds surfaced only marginal review pages.\n")
md.append("## Premise audit (\"no published style guide\")\n")
md.append("- CORRECTION: a WotC house style guide exists — 'D&D Style Guide: Writing and Editing' v1.04a (©2013) and v1.08a (©2018, 'updated January 2019'). Both read in full from PDF text. It governs typography, numerals, verb idiom, capitalization, and one tone paragraph (High Fantasy). It says NOTHING about boxed/read-aloud text.\n- It was public on DMs Guild ~Oct 2018 – ~2020 (EN World 2018-11-25 thread; @dms_guild tweet 2019-02-22; Kind GM commenter May 2020 says gone). Freelancers and AL/Dungeoncraft authors receive it under contract (POCGamer 2021; Dungeoncraft v1.2 'D&D Style Guide (also provided)').\n- Community writers outside that window say none is published: Half-Cover 2017, Old Dungeon Master 2015, Blog of Holding 2025 (for 2024 rules). So: 'no public style guide' is true for 2024-era house style and was true before Oct 2018; false for 2018–2020.\n- v1.04a → v1.08a diff (local): singular 'they' banned → allowed sparingly; '5th Edition' → 'fifth edition'; added headings/sidebar rules, gender-suffix rule, 'fellowship vs party', numeral+abbrev no hyphen ('100 gp treasure'). Nothing on read-aloud in either.\n")
md.append("## Not fetched / not citable\n- dScryb 'Thinking Inside the Box' (Cloudflare block on WebFetch and curl).\n- Goodman Games 2007 seminar PDF (Cloudflare).\n- DMs Guild / DriveThru product pages for the Creator Resource (403) — the package's existence is attested by EN World 2018 thread, Kind GM, sageadvice announcement.\n- 5mwd.com Xanathar review ('cranky Redditor' line) — host dead, Wayback blocked; NOT cited.\n- Kobold Guide to Game Design essays — only store pages found.\n- Decker/Noonan 2005 WotC article on boxed text — not located; known only via Dyson 2013 and a 2025 forum poster (single lineage).\n- WotC Adventure Guide (Perkins/Bilsland tips) inside the Creator Resource — not fetched; contents unknown.\n")
md.append("## Convergent findings across independent craft sources\n- LENGTH: two sentences (Decker/Noonan via Dyson; forum), four sentences/<100 words (Merwin, official-site column), three lines never five (Revivify), <250 words cut 25% (Sly Flourish), paragraph break = too long (DM's Workshop), five-sentence keys (Gus L.). Independent authors, same direction.\n- PERSON: designers split. Merwin (WotC/AL veteran): third person, never 'you'. DM's Workshop: second-person subjective. Style guide: second person in RULES text for gender neutrality. Alexander/Dyson/BAATAG: whatever the person, never dictate PC action, feeling, or entry direction.\n- TENSE: present, never 'will' (Laws 2012; Vallese; Old Dungeon Master 2015).\n- DICTION: evocative-not-conclusory (Lynch), specific-not-generic (Gus L., Skerples, Conowitch), no 'seems/appears' (Merwin), no purple 'fantasy drivil' (Lynch) but no 'Ikea instructions' either (Shea).\n- DM TEXT: sequence by discovery (Alexander), bold interactables (Designing Dungeons, Gus L., Campbell via Davis) vs plain paragraphs (BAATAG), tables over prose (Skerples), map carries geometry (Gus L.).\n- 2024 SHIFT: capitalized glossary terms (Alexander, Blog of Holding), standardized condition phrasing (Old DM), teach-first + annotated play example (Wargamer/Crawford, Idle Cartulary), DMG absorbs adventure boilerplate on doors/boxed text (Perkins/Wyatt via Screen Rant), 'tight and short' sample-adventure scripts (Perkins), 2025 MM one-phrase characterizations and compacted lore (EN World).\n")
md.append("## Sources read (%d; substantive=%d)\n" % (len(S), sum(1 for s in S.values() if s['substantive'])))
for s in S.values():
    md.append("- [%s] %s — %s — %s" % ("S" if s['substantive'] else "-", s['title'], s['kind'], s['url']))
md.append("\n## Claims (%d)\n" % len(C))
for i,c in enumerate(C,1):
    md.append("%d. **%s** — %s\n   - source: %s\n   - url: %s\n   - quote: %s" % (i, c['feature'], c['claim'], c['source'], c['url'], ('"%s"' % c['quote']) if c['quote'] else '(none)'))
open("find-dnd-craft.md","w").write("\n".join(md)+"\n")
print("claims",len(C),"sources",len(S),"substantive",sum(1 for s in S.values() if s['substantive']))
